func TestPrivacyBlurConfig_YAMLRoundTrip(t *testing.T) {
	cfg := PrivacyBlurConfig{
		Enabled:           true,
		Faces:             true,
		Plates:            true,
		BlurRadius:        15.5,
		PixelateBlockSize: 8,
	}

	data, err := yaml.Marshal(cfg)
	require.NoError(t, err)

	var got PrivacyBlurConfig
	require.NoError(t, yaml.Unmarshal(data, &got))

	assert.Equal(t, cfg, got)
}

func TestPrivacyBlurConfig_YAMLParse(t *testing.T) {
	yamlData := `
enabled: true
faces: true
plates: false
blur_radius: 20
pixelate_block_size: 10
`
	var cfg PrivacyBlurConfig
	require.NoError(t, yaml.Unmarshal([]byte(yamlData), &cfg))

	assert.True(t, cfg.Enabled)
	assert.True(t, cfg.Faces)
	assert.False(t, cfg.Plates)
	assert.Equal(t, float64(20), cfg.BlurRadius)
	assert.Equal(t, 10, cfg.PixelateBlockSize)
}

