func TestForwardConfig_WithPrivacyBlur(t *testing.T) {
	yamlData := `
destination:
  url: "rtmp://example.com/live/stream"
privacy_blur:
  enabled: true
  faces: true
  blur_radius: 15
`
	var cfg ForwardConfig
	require.NoError(t, yaml.Unmarshal([]byte(yamlData), &cfg))

	require.NotNil(t, cfg.PrivacyBlur)
	assert.True(t, cfg.PrivacyBlur.Enabled)
	assert.True(t, cfg.PrivacyBlur.Faces)
	assert.Equal(t, float64(15), cfg.PrivacyBlur.BlurRadius)
}

