func TestPrivacyBlurConfig_InFullConfig(t *testing.T) {
	yamlData := `
endpoints:
  /live:
    forwardings:
      - destination:
          url: "rtmp://example.com/live/stream"
        privacy_blur:
          enabled: true
          faces: true
          plates: true
          blur_radius: 25
`
	var buf bytes.Buffer
	buf.WriteString(yamlData)
	var cfg Config
	_, err := cfg.ReadFrom(&buf)
	require.NoError(t, err)

	ep, ok := cfg.Endpoints["/live"]
	require.True(t, ok)
	require.Len(t, ep.Forwardings, 1)
	require.NotNil(t, ep.Forwardings[0].PrivacyBlur)
	assert.True(t, ep.Forwardings[0].PrivacyBlur.Enabled)
	assert.True(t, ep.Forwardings[0].PrivacyBlur.Faces)
	assert.True(t, ep.Forwardings[0].PrivacyBlur.Plates)
	assert.Equal(t, float64(25), ep.Forwardings[0].PrivacyBlur.BlurRadius)
}
